sheet.css:
.pk{--ground:#ecf0f1;--surface:#fff;--ink:#2c3e50;--blue:#20628f;--blue2:#17496b;--blueTint:#2f7fb8;
  --green:#1e8449;--red:#c0392b;--amber:#b9770e;--amberLight:#e8a33d;
  --teal:#117a72;--purple:#6c3fa8;--pink:#b03060;--sand:#f0e2cd;--r:4px;
  background:var(--ground);color:var(--ink);
  font:400 15px/1.5 Roboto,'Open Sans',ui-sans-serif,system-ui,sans-serif}
[data-theme=dark].pk,[data-theme=dark] .pk{--ground:#1b2631;--surface:#22303c;--ink:#eaf0f2;
  --blue:#5dade2;--blue2:#85c1e9;--blueTint:#3d9ad4;
  --teal:#48c9b0;--purple:#a569bd;--pink:#e08aab;--sand:#3d3427;--amberLight:#c98a2a}
.stage.pk{--page:var(--ground);background:var(--ground)}
.pk h3,.pk h4{margin:0;font-weight:700;line-height:1.15}
.pk p{margin:0}
.card{background:var(--surface);border-radius:var(--r);padding:18px}
.pk-btn{font:700 14px/1 inherit;background:var(--blue);color:#fff;border:0;border-radius:var(--r);
  padding:12px 20px;cursor:pointer;transition:background .12s}
.pk-btn:hover{background:var(--blue2)}
.pk-btn:active{background:var(--blue2)}
.pk-btn:focus-visible{outline:3px solid var(--ink);outline-offset:2px}
.pk-btn.g{background:var(--green)}.pk-btn.r{background:var(--red)}
.pk-btn.sec{background:transparent;color:var(--blue2);border:2px solid var(--blue2);padding:10px 18px}
/* uses the PRESSED value for text, not the base: #2f7fb8 on the #ecf0f1 ground is 3.77:1,
   under the 4.5:1 that 14px bold needs. #20628f clears it. */
.pk-btn[disabled]{background:#95a5a6;cursor:not-allowed}
.f-hover{background:var(--blue2)!important}
.f-focus{outline:3px solid var(--ink);outline-offset:2px}
.pk-field{width:100%;background:var(--surface);color:var(--ink);border:2px solid #b9c4c9;
  border-radius:var(--r);padding:10px 12px;font:400 15px/1.2 inherit}
.pk-field:focus-visible{outline:3px solid var(--ink);outline-offset:2px;border-color:var(--blue)}
.pk-field.err{border-color:var(--red)}
.pk-label{display:block;font-weight:700;font-size:13px;margin-bottom:6px}
.pk-err{margin-top:7px;font-size:13px;font-weight:700;color:var(--red)}
.pk-nav{background:var(--ink);border-radius:var(--r);padding:10px 14px;display:flex;
  align-items:center;gap:6px}
.pk-nav .brand{color:#fff;font-weight:700;margin-right:10px}
.pk-nav a{color:#f4f7f8;text-decoration:none;font-size:14px;padding:8px 11px;border-radius:var(--r)}
/* #dfe6e9 on the #2c3e50 bar is 4.33:1 — just under the 4.5 that 14px regular needs. */
.pk-nav a[aria-current]{background:var(--blue2);color:#fff}
/* the PRESSED blue, not the base: white on #2f7fb8 is 4.33:1 and misses 4.5 for 14px.
   White on #20628f is 6.3:1. A flat palette needs a fill that carries white BODY text,
   not just white bold text. */
.pk-nav .sp{flex:1}
table.pk-t{width:100%;border-collapse:collapse;font-size:14px;background:var(--surface);
  border-radius:var(--r);overflow:hidden}
table.pk-t th{text-align:left;background:var(--ink);color:#fff;font-size:12px;padding:10px 14px}
table.pk-t td{padding:11px 14px}
table.pk-t tr:nth-child(even) td{background:rgba(0,0,0,.045)}
[data-theme=dark] table.pk-t tr:nth-child(even) td{background:rgba(255,255,255,.06)}
.pk-scrim{background:rgba(44,62,80,.72);border-radius:var(--r);padding:34px 18px;display:flex;justify-content:center}
.pk-empty{border:2px dashed #b9c4c9;border-radius:var(--r);padding:24px;text-align:center}
.pk-skel{height:12px;background:#d5dbdb;border-radius:var(--r);margin-bottom:9px}
[data-theme=dark] .pk-skel{background:#34495e}
.swatch{border:0;border-radius:4px;height:54px}

page.css:
.s{padding-block:clamp(48px,7vw,96px)}
.band{padding:clamp(32px,5vw,72px) clamp(20px,4vw,56px)}
.hold{max-width:1240px;margin-inline:auto}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}
.g2{display:grid;grid-template-columns:1.1fr .9fr;gap:clamp(24px,4vw,56px);align-items:center}
@media(max-width:860px){.g2{grid-template-columns:1fr}}

/* ── flat ILLUSTRATION. Vector, not photographic — so SVG is the right medium
   here, and Gate 2.5's "a real thing is a raster" does not apply to a
   geometric scene that was never a photograph. ────────────────────────────── */
.illo{width:100%;height:auto;display:block}

/* An outline button inherits the pack's primary, which is tuned against the PAGE
   ground. Drop it on a coloured band and that assumption breaks: #17496b on the
   amber is 2.59:1. On any coloured band, outline controls take ink or white —
   whichever the band itself is carrying. */

/* ── icon tiles: one flat hue each, ink or white text derived per fill ────── */
.tile{padding:24px;border-radius:var(--r);color:#fff}
.tile h3{font-size:19px;margin:0 0 8px}
.tile p{font-size:14px;margin:0;opacity:.95}
.tile svg{width:34px;height:34px;display:block;margin-bottom:14px}
.t1{background:var(--blue)}.t2{background:var(--green)}.t3{background:var(--purple)}
.t4{background:var(--teal)}.t5{background:var(--pink)}.t6{background:var(--amber)}
.tile.ink{background:var(--sand);color:var(--ink)}

.stat{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}
.stat > div{background:var(--surface);border-radius:var(--r);padding:20px}
.stat b{display:block;font-size:32px;line-height:1;margin-bottom:6px}
.blob{border-radius:50%}
